+    if constexpr (!std::is_same_v<Specialize, void> &&
+                  std::is_same_v<Layout, Kokkos::LayoutRight>) {
+      if (layout.dimension[6] == unspecified) {
+        new_layout.stride = unspecified;
+      } else {
+        new_layout.stride = layout.stride;
+      }
+    } else
+#endif
+      new_layout.stride = layout.stride;
